from pathlib import Path
from html.parser import HTMLParser
import re, sys
out=Path('/app/output')
required=['index.html','platform-overview.html','security.html','integration.html','request-demo.html','styles.css','app.js']
missing=[f for f in required if not (out/f).exists()]
print('missing', missing)
class P(HTMLParser):
 def __init__(self): super().__init__(); self.tags=[]; self.links=[]; self.scripts=[]; self.styles=[]
 def handle_starttag(self, tag, attrs):
  self.tags.append(tag); d=dict(attrs)
  if tag=='a' and 'href' in d: self.links.append(d['href'])
  if tag=='script' and 'src' in d: self.scripts.append(d['src'])
  if tag=='link' and d.get('rel')=='stylesheet': self.styles.append(d.get('href'))
for html in out.glob('*.html'):
 p=P(); p.feed(html.read_text())
 print(html.name, 'tags', len(p.tags), 'links', len(p.links), 'scripts', p.scripts, 'styles', p.styles)
 for href in p.links+p.scripts+p.styles:
  if href.startswith(('http','#','mailto:','tel:')): continue
  target=href.split('#')[0]
  if target and not (out/target).exists(): print('BROKEN', html.name, href)
css=(out/'styles.css').read_text()
print('css invalid inset-top?', 'inset-top' in css)
for token in ['GET REAL-TIME DATA','Drilling & Completions Management','80','SOC 1 & 2 Certified Compliance','Read-Only Snowflake Access','REQUEST A DEMO']:
 found=any(token in p.read_text() for p in out.glob('*.html'))
 print(token, found)
